// Detecta alterações manuais no Lists e reinjeta no mesmo fluxo do WhatsApp.
const BASE = 'http://127.0.0.1:5678/webhook/';
const OP_ATIVO = ['Aguardando Operacional e Sistemas', 'Aguardando Operacional'];
const SIS_ATIVO = ['Aguardando Operacional e Sistemas', 'Aguardando Sistemas'];

const voto = (path, pollKey, opcao) => ({
  url: BASE + path,
  body: { event: 'poll.vote', origem: 'lists',
    payload: { poll: { id: 'lists_' + pollKey }, vote: { selectedOptions: [opcao] } } }
});
const justificativa = (path, id, texto) => ({
  url: BASE + path,
  body: { origem: 'lists', itemId: id, justificativa: texto }
});

const saida = [];
for (const item of $input.all()) {
  const f = item.json.fields || {};
  const id = String(item.json.id);
  const p = f.Processamento;
  let acao = null;

  // 1) Comercial (Recuperado / Não Recuperado)
  if (p === 'Aguardando Comercial' && f.StatusComercial === 'Aguardando' && f.PollKeyComercial) {
    const op = { 'Recuperado': '✅ Cliente Recuperado', 'Não Recuperado': '❌ Cliente Não Recuperado' }[f.ClienteRecuperado];
    if (op) acao = { tipo: 'Comercial', ...voto('Resposta-Enquete-Comercial', f.PollKeyComercial, op) };
  }
  // 2) Justificativa Comercial digitada no Lists
  const obsC = String(f.Observa_x00e7__x00e3_oComercial || '').trim();
  if (!acao && p === 'Aguardando Comercial' && f.StatusComercial === 'Aguardando Observação' && obsC) {
    acao = { tipo: 'Justificativa Comercial', ...justificativa('Observacao-Comercial', id, obsC) };
  }
  // 3) Placa
  if (!acao && OP_ATIVO.includes(p) && f.StatusOperacional === 'Aguardando' && f.PollKeyOperacional) {
    const op = { 'Retirada': '✅ Placa Retirada', 'Não Retirada': '⚠️ Placa Não Retirada' }[f.PlacaRemovida];
    if (op) acao = { tipo: 'Placa', ...voto('Resposta-Operacional', f.PollKeyOperacional, op) };
  }
  // 4) Justificativa Operacional digitada no Lists
  const obsO = String(f.Observa_x00e7__x00e3_oOperaciona || '').trim();
  if (!acao && OP_ATIVO.includes(p) && f.StatusOperacional === 'Aguardando Observação' && obsO) {
    acao = { tipo: 'Justificativa Operacional', ...justificativa('Observacao-Operacional', id, obsO) };
  }
  // 5) Sistemas
  if (!acao && SIS_ATIVO.includes(p) && f.RetiradodoFindMe_x003f_ === 'Retirado' && f.PollKeySistemas) {
    acao = { tipo: 'Sistemas', ...voto('Resposta-Operacional', f.PollKeySistemas, '✅ Retirado dos Sistemas') };
  }

  if (acao) saida.push({ json: { itemId: id, ...acao } });
}
return saida;
